)}\n.prow.bad{border-color:var(--accent-alt);border-left-width:4px}\n.prow.done{opacity:.55}\n.prow.done .tt{text-decoration:line-through}\n.pbody{flex:1;min-width:0;display:flex;flex-direction:column;gap:2px}\n.rmain{display:flex;flex-wrap:wrap;align-items:baseline;gap:1px 8px;width:100%;min-width:0;border:0;background:transparent;padding:0;text-align:left;color:var(--ink)}\n.cf{font-size:10.5px;line-height:1.4}\n.chk{flex:none;width:20px;height:20px;margin-top:1px;border-radius:6px;border:1.5px solid var(--accent);background:transparent;padding:0;position:relative}\n.chk.on{background:var(--accent)}\n.chk.on::after{content:\"\";position:absolute;left:6px;top:2px;width:5px;height:10px;border:solid var(--on-accent);border-width:0 2px 2px 0;transform:rotate(45deg)}\n.selbar{display:flex;gap:12px}\n\n.frow2{display:flex;align-items:flex-start;gap:8px;padding:5px 0;border-bottom:1px solid var(--line)}\n.frow2 .wd{flex:none;width:32px;padding-top:4px;font-size:11px}\n.frow2 .chips{flex:1;min-width:0}\n.chips{display:flex;flex-wrap:wrap;gap:4px;min-width:0}\n.chip{min-width:30px;height:26px;padding:0 8px;border-radius:999px;border:1px solid var(--line);background:transparent;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.setbox{display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--line);border-radius:9px;background:var(--panel-paper)}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}\n.lab{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-width:0;height:30px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:0 6px;font:inherit}\n.inp:focus{outline:2px solid var(--accent);outline-offset:0}\n.frow{display:flex;gap:6px;min-width:0}\n.form{flex:1;display:flex;flex-direction:column;gap:6px;min-height:0;min-width:0;width:100%;max-width:420px;margin:0 au