1;width:auto}\n.card[data-size^=\"6\"] .tabs{flex-direction:column}\n.card[data-size^=\"6\"] .tab{flex:none;height:26px;text-align:left;padding:0 8px;font-size:12px}\n.card[data-size^=\"6\"] .tab .cnt{display:inline;float:right;font-variant-numeric:tabular-nums;opacity:.8}\n.card[data-size=\"6x6\"]{padding:12px}\n.card[data-size=\"6x6\"] .brand{display:block}\n.card[data-size=\"6x6\"] .tab{height:32px}\n.card[data-size=\"6x6\"] .scroll{gap:6px}\n.card[data-size=\"6x6\"] .bar{height:60px}\n.card[data-size=\"6x6\"] .row,.card[data-size=\"6x6\"] .prow{padding:8px 10px}\n.card[data-size=\"3x6\"] .scroll{gap:5px}\n@media (prefers-reduced-motion:no-preference){.tab,.chip,.btn{transition:background-color .15s,border-color .15s}}\n";
function mount(ctx){
const {root,el,state,ui,update,commit,redraw,uid,day,size}=ctx;
var WN=['周一','周二','周三','周四','周五','周六','周日'];
var WS=['一','二','三','四','五','六','日'];
function pad(n){return n<10?'0'+n:''+n}
function t2m(t){var p=String(t||'').split(':');return (+p[0]||0)*60+(+p[1]||0)}
function m2t(m){return pad(Math.floor(m/60))+':'+pad(m%60)}
function pd(s){var p=String(s).split('-');return new Date(+p[0],(+p[1]||1)-1,+p[2]||1)}
function fd(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function addD(s,n){var d=pd(s);d.setDate(d.getDate()+n);return fd(d)}
function wdOf(s){return (pd(s).getDay()+6)%7}
function mondayOf(s){return addD(s,-wdOf(s))}
function md(s){var d=pd(s);return (d.getMonth()+1)+'/'+d.getDate()}
function fmtDur(m){m=Math.round(m);if(m<=0)return '0分';if(m<60)return m+'分';var h=Math.floor(m/60),r=m%60;return r?h+'小时'+r+'分':h+'小时'}
function norm(s){
  s=s||{};
  var st=s.settings||{};
  return Object.assign({},s,{
    tasks:Array.isArray(s.tasks)?s.tasks:[],
    meetings:Array.isArray(s.meetings)?s.meetings:[],
    avail:Array.isArray(s.avail)?s.avail:[],
    plans:(s.plans&&typeof s.plans==='object'&&!Array.isArray(s.plans))?s.plans:{},
    settings:{mode:st.mode||'early',chunk:+st.chunk||90,gap:st.gap===undefined?10:+st.gap}
  });
}
function occurs(m,ds){return ds===m.date||(m.repeat==='weekly'&&ds>m.date&&wdOf(ds)===wdOf(m.date))}
function meetOn(S,ds){
  return S.meetings.filter(function(m){return occurs(m,ds)&&t2m(m.end)>t2m(m.start)})
    .sort(function(a,b){return t2m(a.start)-t2m(b.start)});
}
function mergeW(w){
  var o=[];
  w.slice().sort(function(a,b){return a[0]-b[0]}).forEach(function(x){
    var l=o[o.length-1];
    if(l&&x[0]<=l[1])l[1]=Math.max(l[1],x[1]);else o.push([x[0],x[1]]);
  });
  return o;
}
function winsOf(S,ds){
  var wd=wdOf(ds);
  return mergeW(S.avail.filter(function(a){return a.wd===wd&&t2m(a.end)>t2m(a.start)})
    .map(function(a){return [t2m(a.start),t2m(a.end)]}));
}
function subtract(wins,busy){
  var out=wins.map(function(w){return [w[0],w[1]]});
  busy.forEach(function(b){
    var nx=[];
    out.forEach(function(w){
      if(b[1]<=w[0]||b[0]>=w[1]){nx.push(w);return}
      if(b[0]>w[0])nx.push([w[0],b[0]]);
      if(b[1]<w[1])nx.push([b[1],w[1]]);
    });
    out=nx;
  });
  return out.sort(function(a,b){return a[0]-b[0]});
}
function sum(sl){return sl.reduce(function(t,w){return t+(w[1]-w[0])},0)}
function dayInfo(S,ds,its){
  var wins=winsOf(S,ds),win=sum(wins);
  var a1=subtract(wins,meetOn(S,ds).map(function(m){return [t2m(m.start),t2m(m.end)]}));
  var pb=(its||[]).filter(function(i){return i.date===ds}).map(function(i){return [t2m(i.start),t2m(i.end)]});
  var a2=subtract(a1,pb);
  return {win:win,meet:win-sum(a1),plan:sum(a1)-sum(a2),free:sum(a2)};
}

function otherMap(S,ws){
  var o={};
  Object.keys(S.plans).forEach(function(k){
    if(k===ws)return;
    ((S.plans[k]||{}).items||[]).forEach(function(it){o[it.taskId]=(o[it.taskId]||0)+Math.max(0,t2m(it.end)-t2m(it.start))});
  });
  return o;
}
function cmpIt(a,b){return a.date<b.date?-1:a.date>b.date?1:t2m(a.start)-t2m(b.start)}
function ceil5(x){return Math.ceil(x/5)*5}
function makePlan(S,ws,today,nowMin){
  var gap=S.settings.gap,M=S.settings.chunk,mode=S.settings.mode,days=[],items=[],un=[];
  for(var i=0;i<7;i++){
    var ds=addD(ws,i);
    if(ds<today)continue;
    var busy=meetOn(S,ds).map(function(m){return [t2m(m.start)-gap,t2m(m.end)+gap]});
    if(ds===today)busy.push([0,ceil5(nowMin)]);
    days.push({ds:ds,busy:busy,load:0,wins:winsOf(S,ds)});
  }
  var other=otherMap(S,ws),rank={'高':0,'中':1,'低':2};
  var tasks=S.tasks.map(function(t,k){return {t:t,i:k}}).filter(function(x){return !x.t.done}).sort(function(a,b){
    var da=a.t.due||'9999',db=b.t.due||'9999';
    if(da!==db)return da<db?-1:1;
    var pa=rank[a.t.pri]===undefined?1:rank[a.t.pri],pb=rank[b.t.pri]===undefined?1:rank[b.t.pri];
    return pa!==pb?pa-pb:a.i-b.i;
  }).map(function(x){return x.t});
  tasks.forEach(function(t){
    var left=Math.max(0,(+t.minutes||0)-(other[t.id]||0)),guard=0;
    while(left>0&&guard++<40){
      var want=left<=M?left:(left-M<30?left-30:M);
      var minc=Math.min(want,30),full=[],part=[];
      days.forEach(function(d){
        if(t.due&&d.ds>t.due)return;
        var f=null,p=null;
        subtract(d.wins,d.busy).forEach(function(w){
          var a=ceil5(w[0]),len=w[1]-a;
          if(len>=want&&!f)f={d:d,a:a,len:want};
          var pl=Math.floor(len/5)*5;
          if(pl>=minc&&(!p||pl>p.len))p={d:d,a:a,len:Math.min(pl,want)};
        });
        if(f)full.push(f);else if(p)part.push(p);
      });
      var pool=full.length?full:part;
      if(!pool.length)break;
      var pick=pool[0];
      if(mode==='even')pool.forEach(function(c){if(c.d.load<pick.d.load)pick=c});
      items.push({id:uid(),taskId:t.id,title:t.title,date:pick.d.ds,start:m2t(pick.a),end:m2t(pick.a+pick.len),sel:true,edited:false});
      pick.d.busy.push([pick.a-gap,pick.a+pick.len+gap]);
      pick.d.load+=pick.len;
      left-=pick.len;
    }
    if(left>0){
      var why='本周空闲时间不够';
      if(!S.avail.length)why='还没填空闲时间';
      else if(!days.length)why='本周已经过完';
      else if(t.due&&t.due<days[0].ds)why='截止日已过';
      else if(t.due&&t.due<addD(ws,6))why='截止日 '+md(t.due)+' 前空闲时间不够';
      un.push({taskId:t.id,title:t.title,left:left,reason:why});
    }
  });
  return {items:items.sort(cmpIt),unplaced:un,genAt:Date.now()};
}
function conflictsOf(S,it,all){
  var a=t2m(it.start),b=t2m(it.end),out=[];
  meetOn(S,it.date).forEach(function(m){
    if(a<t2m(m.end)&&b>t2m(m.start))out.push({hard:true,t:'与会议「'+m.title+'」时间重叠'});
  });
  all.forEach(function(o){
    if(o.id!==it.id&&o.date===it.date&&a<t2m(o.end)&&b>t2m(o.start))out.push({hard:true,t:'与安排「'+o.title+'」重叠'});
  });
  if(!winsOf(S,it.date).some(function(x){return a>=x[0]&&b<=x[1]}))out.push({hard:false,t:'超出你填的空闲时段'});
  var task=S.tasks.filter(function(t){return t.id===it.taskId})[0];
  if(task&&task.due&&it.date>task.due)out.push({hard:false,t:'晚于截止日 '+md(task.due)});
  return out;
}

const sz=size||(root.getAttribute&&root.getAttribute('data-size'))||'6x6';
const big=sz==='6x6'||sz==='3x6';
const S=norm(state);
const today=day();
if(!ui.ws)ui.ws=mondayOf(today);
if(!ui.tab)ui.tab='cal';
const ws=ui.ws;
const wk=[];for(let i=0;i<7;i++)wk.push(addD(ws,i));
const plan=S.plans[ws]||null;
const items=plan&&Array.isArray(plan.items)?plan.items:[];
const openT=S.tasks.filter(t=>!t.done);
const other=otherMap(S,ws);
const h=(tag,cls,...kids)=>el(tag,{class:cls},...kids.flat().filter(k=>k!==null&&k!==undefined&&k!==false));
const btn=(label,cls,fn,attrs)=>el('button',Object.assign({type:'button',class:cls,onclick:fn},attrs||{}),label);
const btnK=(cls,fn,...kids)=>el('button',{type:'button',class:cls,onclick:fn},...kids.flat().filter(k=>k!==null&&k!==undefined&&k!==false));
const go=(p)=>{Object.assign(ui,{notice:'',rg:false},p);redraw()};
const fail=()=>{ui.notice='保存失败，请稍后再试';redraw()};
const ch=(n,p)=>Object.assign({},n,p);
const upd=(fn)=>{update(s=>fn(norm(s))).catch(fail)};
const setPlan=(n,fn)=>{
  const p=n.plans[ws];
  if(!p)return n;
  return ch(n,{plans:Object.assign({},n.plans,{[ws]:Object.assign({},p,fn(p))})});
};
const chk=(on,fn,label)=>el('button',{type:'button',class:'chk'+(on?' on':''),onclick:fn,'aria-label':label,'aria-pressed':on?'true':'false'});
const withDis=(attrs,off)=>{if(off)attrs.disabled=true;return attrs};

const toggleDone=(id)=>upd(n=>ch(n,{tasks:n.tasks.map(t=>t.id===id?Object.assign({},t,{done:!t.done}):t)}));
const toggleSel=(id)=>upd(n=>setPlan(n,p=>({items:p.items.map(i=>i.id===id?Object.assign({},i,{sel:!i.sel}):i)})));
const setSel=(v)=>upd(n=>setPlan(n,p=>({items:p.items.map(i=>Object.assign({},i,{sel:v}))})));
const setSet=(k,v)=>upd(n=>ch(n,{settings:Object.assign({},n.settings,{[k]:v})}));
const generate=()=>{
  const needAsk=plan&&items.some(i=>i.edited);
  if(needAsk&&!ui.rg){go({rg:true});return}
  const nd=new Date(),nm=nd.getHours()*60+nd.getMinutes();
  ui.rg=false;
  upd(n=>ch(n,{plans:Object.assign({},n.plans,{[ws]:makePlan(n,ws,today,nm)})}));
};

const openForm=(k,id,draft)=>{Object.assign(ui,{edit:{k:k,id:id||null},draft:draft,err:'',arm:false,busy:false,notice:'',calMsg:''});redraw()};
const closeForm=()=>{Object.assign(ui,{edit:null,draft:null,err:'',arm:false,busy:false,calMsg:''});redraw()};
const defDate=()=>wk.includes(today)?today:ws;
const openMeet=(m)=>openForm('meet',m&&m.id,m?{title:m.title,date:m.date,start:m.start,end:m.end,repeat:m.repeat||'none'}:{title:'',date:defDate(),start:'',end:'',repeat:'none'});
