  if(f.t==='choice')return h('div','fld',h('div','lab',f.label),h('div','chips',f.opts.map(o=>btn(o[1],'chip'+(d[f.k]===o[0]?' on':''),()=>{d[f.k]=o[0];ui.err='';redraw()}))));
  if(f.t==='days'){
    const set=(a)=>()=>{d.days=a;ui.err='';redraw()};
