      h('div','chips',WS.map((w,i)=>btn(w,'chip'+(d.days.includes(i)?' on':''),()=>{d.days=d.days.includes(i)?d.days.filter(x=>x!==i):d.days.concat(i);ui.err='';redraw()}))),
