const dayHead=(ds)=>h('div','dh'+(ds===today?' today':''),WN[wdOf(ds)],h('span','dd',md(ds)),ds===today?h('span','tag','今天'):null);
function strip(){
  const infos=wk.map(ds=>dayInfo(S,ds,items));
  const mx=Math.max(60,...infos.map(i=>i.win));
  const cols=wk.map((ds,i)=>{
    const f=infos[i];
    const col=h('div','col');
    col.style.height=(f.win?Math.max(6,f.win/mx*100):0)+'%';
    [['free',f.free],['plan',f.plan],['meet',f.meet]].forEach(p=>{
      if(p[1]<=0)return;
      const sg=h('div','sg '+p[0]);
      sg.style.flexGrow=String(p[1]);
      col.appendChild(sg);
    });
    const bar=h('div','bar',f.win?col:h('div','nowin'));
    return h('div','sc'+(ds===today?' today':''),bar,h('div','wl',WS[i]));
  });
  return h('div','stripbox',h('div','strip',cols),
    h('div','lg',h('span','','空闲窗口：'),h('span','','会议'),h('span','','新安排'),h('span','','剩余')));
}
function calBody(){
  const out=[h('div','note','日历读取未接入：请手动填本周会议，排程只绕开它们、不改动。')];
  if(big)out.push(strip());
  let any=false;
  wk.forEach(ds=>{
    const ms=meetOn(S,ds);
    if(!ms.length)return;
    any=true;
    out.push(dayHead(ds));
    ms.forEach(m=>out.push(btnK('row',()=>openMeet(m),h('span','tm',m.start+'–'+m.end),h('span','tt',m.title),m.repeat==='weekly'?h('span','tag','每周'):null)));
  });
  if(!any)out.push(h('div','empty','本周还没有填会议。没有会议也可以直接去填待办。'));
  return out;
}
function todoBody(){
  const out=[];
  const tot=openT.reduce((t,x)=>t+(+x.minutes||0),0);
  out.push(h('div','cap','未完成 ',h('b','',String(openT.length)),' 项 · 共 ',h('b','',fmtDur(tot))));
  if(!S.tasks.length)out.push(h('div','empty','还没有待办。填上事项和预计用时，就能排进空闲时间。'));
  S.tasks.slice().sort((a,b)=>(a.done?1:0)-(b.done?1:0)).forEach(t=>{
    const meta=[t.due?'截止 '+md(t.due):'无截止日','优先级'+(t.pri||'中')];
    if(other[t.id])meta.push('其他周已排 '+fmtDur(other[t.id]));
    out.push(h('div','prow'+(t.done?' done':''),
      chk(!!t.done,()=>toggleDone(t.id),t.done?'标为未完成':'标为已完成'),
      h('div','pbody',btnK('rmain',()=>openTodo(t),h('span','tt',t.title),h('span','dur',fmtDur(t.minutes))),h('div','sub',meta.join(' · ')))));
  });
  return out;
}
function freeBody(){
  const out=[h('div','note','填每天能用来做事的时段，每周重复使用。会议会自动从中扣掉。')];
  WN.forEach((w,i)=>{
    const ls=S.avail.filter(a=>a.wd===i&&t2m(a.end)>t2m(a.start)).sort((a,b)=>t2m(a.start)-t2m(b.start));
    out.push(h('div','frow2',h('b','wd',w),h('div','chips',ls.length?ls.map(a=>btn(a.start+'–'+a.end,'chip',()=>openAvail(a))):[h('span','muted','未设置')])));
  });
  return out;
}
function planRow(it){
  const cf=conflictsOf(S,it,items);
  const dur=t2m(it.end)-t2m(it.start);
  return h('div','prow'+(cf.some(c=>c.hard)?' bad':''),
    chk(!!it.sel,()=>toggleSel(it.id),it.sel?'不加入日历':'加入日历'),
    h('div','pbody',
      btnK('rmain',()=>openItem(it),h('span','tm',it.start+'–'+it.end),h('span','tt',it.title),h('span','dur',fmtDur(dur))),
      cf.length?h('div','cf','注意：'+cf.map(c=>c.t).join('；')):null));
}
function setBox(){
  const grp=(label,key,opts)=>h('div','fld',h('div','lab',label),h('div','chips',opts.map(o=>btn(o[1],'chip'+(S.settings[key]===o[0]?' on':''),()=>setSet(key,o[0])))));
  return h('div','setbox',
    grp('排法','mode',[['early','尽早排'],['even','每天均匀']]),
    grp('单段最长','chunk',[45,60,90,120,180].map(m=>[m,fmtDur(m)])),
    grp('段间留白','gap',[0,10,15,30].map(m=>[m,m+'分'])),
    h('div','sub','改设置后点“重新生成”才会生效。'));
}
function planBody(){
  const out=[];
  const needed=openT.reduce((t,x)=>t+Math.max(0,(+x.minutes||0)-(other[x.id]||0)),0);
  const avail=wk.filter(ds=>ds>=today).reduce((t,ds)=>{const i=dayInfo(S,ds,[]);return t+i.win-i.meet},0);
  out.push(h('div','cap','待排 ',h('b','',fmtDur(needed)),' · 空闲 ',h('b','',fmtDur(avail)),needed>avail?' · 空闲不够，会有排不下的':''));
  out.push(btn(ui.showSet?'收起排法设置':'排法设置','link',()=>go({showSet:!ui.showSet})));
  if(ui.showSet)out.push(setBox());
  if(big)out.push(strip());
  if(!plan){
    const hints=[];
    if(!openT.length)hints.push('先去「待办」添加事项和预计用时。');
    if(!S.avail.length)hints.push('再去「空闲」填每天能用的时段。');
    out.push(h('div','empty',hints.length?hints.join(' '):'点“生成安排”，会按截止日和优先级把待办排进空闲时段，避开所有会议。生成后你可以先改，再选择加入哪些。'));
    return out;
  }
  const g=new Date(plan.genAt||0);
  out.push(h('div','sub','生成于 '+md(fd(g))+' '+m2t(g.getHours()*60+g.getMinutes())+' · 点安排可改日期和时间，勾选的才会加入'));
  if(items.length){
    out.push(h('div','selbar',btn('全选','link',()=>setSel(true)),btn('全不选','link',()=>setSel(false))));
  }else out.push(h('div','empty','没有排进任何事项。'));
  wk.forEach(ds=>{
    const its=items.filter(i=>i.date===ds);
    if(!its.length)return;
    out.push(dayHead(ds));
    const all=meetOn(S,ds).map(m=>({m:m,s:t2m(m.start)})).concat(its.map(i=>({i:i,s:t2m(i.start)}))).sort((a,b)=>a.s-b.s);
    all.forEach(x=>out.push(x.i?planRow(x.i):h('div','row fixed',h('span','tm',x.m.start+'–'+x.m.end),h('span','tt',x.m.title),h('span','tag','会议·固定'))));
  });
  const un=plan.unplaced||[];
  if(un.length){
    out.push(h('div','dh','没排下'));
    un.forEach(u=>out.push(h('div','row un',h('span','tt',u.title),h('span','dur','还差 '+fmtDur(u.left)),h('span','sub',u.reason))));
  }
  return out;
}

function render(){
  if(ui.edit){
    root.appendChild(h('div','shell',editView()));
    return;
  }
  const isCur=ws===mondayOf(today);
  const meetCount=wk.reduce((t,ds)=>t+meetOn(S,ds).length,0);
  const selCount=items.filter(i=>i.sel).length;
  const TABS=[['cal','日历',meetCount],['todo','待办',openT.length],['free','空闲',S.avail.length],['plan','计划',items.length]];
  if(!TABS.some(t=>t[0]===ui.tab))ui.tab='cal';
  const nav=h('div','nav',
    btn('‹','ic',()=>go({ws:addD(ws,-7)}),{'aria-label':'上一周'}),
    btnK('lbl',()=>go({ws:mondayOf(today)}),md(ws)+'–'+md(addD(ws,6)),h('span','cur',isCur?'本周':'回到本周')),
    btn('›','ic',()=>go({ws:addD(ws,7)}),{'aria-label':'下一周'}));
  const tabs=h('div','tabs',TABS.map((t,i)=>btnK('tab'+(ui.tab===t[0]?' on':''),()=>go({tab:t[0]}),h('span','n',String(i+1)),t[1],t[2]?h('span','cnt',String(t[2])):null)));
  let body,foot;
  if(ui.tab==='cal'){
    body=calBody();
    foot=[btn('＋ 添加会议','btn pri',()=>openMeet(null))];
  }else if(ui.tab==='todo'){
    body=todoBody();
    foot=[btn('＋ 添加待办','btn pri',()=>openTodo(null))];
  }else if(ui.tab==='free'){
    body=freeBody();
    foot=[btn('＋ 添加时段','btn pri',()=>openAvail(null))];
  }else{
    body=planBody();
    const canGen=openT.length>0&&S.avail.length>0;
    if(!plan){
      foot=[el('button',withDis({type:'button',class:'btn pri',onclick:generate},!canGen),'生成安排')];
    }else{
      foot=[btn(ui.rg?'覆盖已改的？':'重新生成','btn',generate),
        el('button',withDis({type:'button',class:'btn pri',onclick:()=>openForm('confirm',null,{})},!selCount),'加入日历 '+selCount)];
    }
  }
  if(ui.notice)body.unshift(h('div','err','注意：'+ui.notice));
  root.appendChild(h('div','shell',
    h('div','side',h('div','brand','一周安排'),nav,tabs),
    h('div','main',h('div','scroll',body),h('div','foot',foot))));
}
render();
